SELECT 
FROM team_employees te

WHERE te.team_code = #{teamCode}
  AND te.employee_id = #{employeeId}
  AND te.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

SELECT 
FROM team_employees te

WHERE te.team_code = #{teamCode}
  AND te.employee_id = #{employeeId}
  AND te.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@DELETED.value}

SELECT 
FROM team_employees te

WHERE te.team_code = #{teamCode}
  AND te.is_leader = true
  AND te.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

SELECT te.id as te_id, te.team_code as te_team_code, te.employee_id as te_employee_id, te.role_code as te_role_code, te.is_leader as te_is_leader, e.first_name as emp_first_name, e.last_name as emp_last_name, e.image_url as emp_image_url, t.department_code as t_department_code FROM team_employees te
AND te.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
ORDER BY
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*)
FROM team_employees te





    AND te.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

SELECT EXISTS(
    SELECT 1 FROM team_employees 
    WHERE team_code = #{teamCode} AND employee_id = #{employeeId} 
    AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
)

SELECT EXISTS(
    SELECT 1 FROM team_employees 
    WHERE team_code = #{teamCode} AND is_leader = true 
    AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
)

mapper.update:
UPDATE team_employees
SET is_leader = #{isLeader}, updated_at = CURRENT_TIMESTAMP
WHERE team_code = #{teamCode} AND employee_id = #{employeeId}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

UPDATE team_employees
SET delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@DELETED.value},
    deleted_at = CURRENT_TIMESTAMP
WHERE team_code = #{teamCode} AND employee_id = #{employeeId}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

UPDATE team_employees
SET delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value},
    deleted_at = NULL, 
    role_code = #{teamEmployee.roleCode}, 
    is_leader = #{teamEmployee.isLeader}, 
    updated_at = CURRENT_TIMESTAMP
WHERE team_code = #{teamEmployee.teamCode} 
  AND employee_id = #{teamEmployee.employeeId}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@DELETED.value}

UPDATE team_employees
SET role_code = #{roleCode}, updated_at = CURRENT_TIMESTAMP
WHERE team_code = #{teamCode} AND employee_id = #{employeeId}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

mapper.sql:
INNER JOIN employees e ON te.employee_id = e.client_id 
    AND e.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
INNER JOIN teams t ON te.team_code = t.team_code 
    AND t.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
